import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // 1. Stage Backdrop: Dark vertical gradient to satisfy the dark-first design
  const bgGeo = new THREE.PlaneGeometry(8.0, 6.5);

  // Clean, non-washed vertical gradient for background using basic material to avoid light wash
  const bgGrad0 = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);
  const bgGrad1 = vec3(0x05 / 255, 0x05 / 255, 0x08 / 255);
  const bgMat = new MeshBasicNodeMaterial({
    colorNode: mix(bgGrad1, bgGrad0, uv().y),
    depthWrite: false
  });

  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -1.5;
  group.add(bgMesh);

  // 2. Focused Lights for Dramatic Sculpting
  const keyLight = new THREE.DirectionalLight('#ffffff', 1.2);
  keyLight.position.set(2.0, 3.0, 4.0);
  group.add(keyLight);

  const accentRim = new THREE.DirectionalLight('#ff2a38', 0.9);
  accentRim.position.set(-3.0, 2.0, 1.5);
  group.add(accentRim);

  // 3. Main Panel Container (3.4w x 1.9h)
  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const panelGroup = new THREE.Group();
  group.add(panelGroup);

  // High-contrast engineered gradient panel
  const panelGeo = new THREE.PlaneGeometry(panelWidth, panelHeight);
  const pGradColor0 = vec3(0x1a / 255, 0x1a / 255, 0x22 / 255);
  const pGradColor1 = vec3(0x11 / 255, 0x11 / 255, 0x16 / 255);
  const panelColorNode = mix(pGradColor1, pGradColor0, uv().y);

  const panelMat = new MeshPhysicalNodeMaterial({
    colorNode: panelColorNode,
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1
  });

  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  panelGroup.add(panelMesh);

  // Hairline Border (0.006-unit #26262f)
  const borderGeo = new THREE.EdgesGeometry(panelGeo);
  const borderMat = new THREE.LineBasicMaterial({ color: 0x26262f });
  const borderMesh = new THREE.LineSegments(borderGeo, borderMat);
  borderMesh.position.z = 0.01;
  panelGroup.add(borderMesh);

  // 4. Typographic Content & Layout
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const quoteMarkCopy = textItems[0]?.text ?? '"';
  const quoteCopy = textItems[1]?.text ?? "The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.";
  const attributionCopy = textItems[2]?.text ?? "M. OKAFOR";
  const captionCopy = textItems[3]?.text ?? "COLLECTOR SINCE 2019";

  // Oversized Quote Mark (0.62 units tall)
  const quoteMarkMesh = ctx.fontAtlas.createText(quoteMarkCopy, {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left'
  });
  // 0.5 padding from top-left: x = -1.7 + 0.5 = -1.2, y = 0.95 - 0.5 = 0.45
  quoteMarkMesh.position.set(-1.2, 0.45, 0.05);
  quoteMarkMesh.scale.setScalar(0.01);
  panelGroup.add(quoteMarkMesh);

  // Quote text (0.25 below quote mark -> y = 0.20, max width 2.4)
  const formattedQuote = quoteCopy.replace(/(.{1,32})(\s+|$)/g, "$1\n").trim();
  const quoteMesh = ctx.fontAtlas.createText(formattedQuote, {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'left'
  });
  quoteMesh.position.set(-1.2, 0.15, 0.04);
  quoteMesh.scale.setScalar(0.01);
  panelGroup.add(quoteMesh);

  // Accent Rule (led by 0.2w x 0.02h emissive red graphic)
  const ruleGeo = new THREE.PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.4
  });
  const ruleMesh = new THREE.Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-1.1, -0.4, 0.04); // Left edge aligned at -1.2
  panelGroup.add(ruleMesh);

  // Attribution Text
  const attributionMesh = ctx.fontAtlas.createText(attributionCopy, {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.2
  });
  attributionMesh.position.set(-1.2, -0.55, 0.04);
  attributionMesh.scale.setScalar(0.01);
  panelGroup.add(attributionMesh);

  // Caption Text
  const captionMesh = ctx.fontAtlas.createText(captionCopy, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.5
  });
  captionMesh.position.set(-1.2, -0.7, 0.04);
  captionMesh.scale.setScalar(0.01);
  panelGroup.add(captionMesh);

  // 5. Entrance Animations & GSAP Choreography
  const tl = gsap.timeline();

  // Reveal transition for entire panel
  panelGroup.position.y = -0.2;
  panelGroup.position.z = -0.5;

  tl.to(panelGroup.position, {
    y: 0,
    z: 0,
    duration: 0.7,
    ease: 'power3.out'
  });

  // Settling motion specifically on the primary quote mark
  quoteMarkMesh.scale.setScalar(0);
  tl.to(quoteMarkMesh.scale, {
    x: 0.01,
    y: 0.01,
    z: 0.01,
    duration: 0.9,
    ease: 'back.out(1.7)'
  }, 0.2);

  // Apply visual configurations & primitives
  const primitivesList = config.cinematicPrimitives || [];
  const activePrimitives = [];
  primitivesList.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      const activePrim = ctx.primitives[prim.name](group, prim.params);
      activePrimitives.push(activePrim);
    }
  });

  // 6. Cleanup
  group.userData = {
    cleanup: () => {
      tl.kill();
      activePrimitives.forEach(p => p?.cleanup?.());
      bgGeo.dispose();
      bgMat.dispose();
      panelGeo.dispose();
      panelMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      ruleGeo.dispose();
      ruleMat.dispose();
    }
  };

  return group;
}
